-- ============================================
-- SQL Script: Insert/Update All Form Templates
-- Generated for Alazwak Food Safety App
-- Run this in Supabase SQL Editor (Dashboard)
-- ============================================

-- First, let's see what's already in the table
SELECT code, name, category FROM master_templates ORDER BY code;

-- Insert new forms (skip if code already exists)
ON CONFLICT (code) DO UPDATE SET
  name = EXCLUDED.name,
  name_en = EXCLUDED.name_en,
  category = EXCLUDED.category,
  updated_at = NOW();

-- Total: 110 forms